root.command:
IF OBJECT_ID(N'dbo.ContactPortalChangeRequestTbl', N'U') IS NULL BEGIN CREATE TABLE dbo.ContactPortalChangeRequestTbl ( RequestID BIGINT IDENTITY(1,1) NOT NULL CONSTRAINT PK_ContactPortalChangeRequestTbl PRIMARY KEY, ContactID INT NOT NULL, UserId UNIQUEIDENTIFIER NULL, Kind NVARCHAR(32) NOT NULL, RelatedId BIGINT NULL, RequestText NVARCHAR(MAX) NOT NULL, Status NVARCHAR(24) NOT NULL CONSTRAINT DF_ContactPortalCR_Status DEFAULT (N'Open'), CreatedAt DATETIME NOT NULL CONSTRAINT DF_ContactPortalCR_CreatedAt DEFAULT (GETDATE()), ResolvedAt DATETIME NULL, ResolvedBy NVARCHAR(128) NULL, StaffNote NVARCHAR(1000) NULL );
CREATE INDEX IX_ContactPortalCR_ContactCreated ON dbo.ContactPortalChangeRequestTbl (ContactID, CreatedAt DESC);
CREATE INDEX IX_ContactPortalCR_StatusCreated ON dbo.ContactPortalChangeRequestTbl (Status, CreatedAt DESC); END
